Per-fork breakdown — median coefficient

function group_by(arr, key) {
  const m = new Map()
  for (const d of arr) {
    const k = d[key]
    if (!m.has(k)) m.set(k, [])
    m.get(k).push(d)
  }
  return Array.from(m, ([k,v]) =&gt; ({
    key: k, n: v.length,
    median: stats(v, d =&gt; d.coef).median,
    pct_sig_neg: v.filter(d =&gt; d.p &lt; 0.05 && d.coef &lt; 0).length / v.length
  })).sort((a,b) =&gt; a.median - b.median)
}
